// Continuous rotation: each call returns the next quote in order, wrapping at the end.
// The position is stored so the rotation carries on across visits and days.
const QUOTE_INDEX_KEY = "bibleQuoteIndex";

export function nextBibleQuoteIndex(storage = (typeof localStorage !== "undefined" ? localStorage : null)) {
  let last = -1;
  try { last = parseInt(storage && storage.getItem(QUOTE_INDEX_KEY), 10); } catch (e) { last = -1; }
  if (!Number.isFinite(last) || last < 0) last = -1;
  return (last + 1) % BIBLE_QUOTES.length;
}

export function saveBibleQuoteIndex(index, storage = (typeof localStorage !== "undefined" ? localStorage : null)) {
  try { if (storage) storage.setItem(QUOTE_INDEX_KEY, String(index)); } catch (e) { /* storage unavailable */ }
}

export function bibleQuoteAt(index) {
  return BIBLE_QUOTES[((index % BIBLE_QUOTES.length) + BIBLE_QUOTES.length) % BIBLE_QUOTES.length];
}
